/* @autogenerated */
import { CommonModule } from '@angular/common';
import { Component, computed, input, OnDestroy, OnInit, signal } from '@angular/core';
import { FormControl, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { TranslocoModule } from '@jsverse/transloco';
import {
  parsePhoneNumber,
  isValidPhoneNumber,
  CountryCode,
  getCountries,
  getCountryCallingCode,
} from 'libphonenumber-js/min';
import { Subscription } from 'rxjs';
import { BaseEditable } from '../base-editable';

export interface PhoneCountry {
  code: CountryCode;
  dialCode: string;
  flag: string;
  name: string;
}

const COUNTRY_NAMES: Partial<Record<CountryCode, string>> = {
  ES: 'España',
  US: 'United States',
  GB: 'United Kingdom',
  DE: 'Deutschland',
  FR: 'France',
  IT: 'Italia',
  PT: 'Portugal',
  MX: 'México',
  AR: 'Argentina',
  CO: 'Colombia',
  CL: 'Chile',
  BR: 'Brasil',
  AU: 'Australia',
  CA: 'Canada',
  JP: 'Japan',
  CN: 'China',
  IN: 'India',
  RU: 'Russia',
  ZA: 'South Africa',
};

function countryToFlag(code: string): string {
  return code
    .toUpperCase()
    .split('')
    .map((c) => String.fromCodePoint(0x1f1e0 - 65 + c.charCodeAt(0)))
    .join('');
}

const ALL_COUNTRIES: PhoneCountry[] = getCountries()
  .map((code) => {
    try {
      return {
        code,
        dialCode: '+' + getCountryCallingCode(code),
        flag: countryToFlag(code),
        name: COUNTRY_NAMES[code] ?? code,
      };
    } catch {
      return null;
    }
  })
  .filter(Boolean) as PhoneCountry[];

@Component({
  selector: 'editable-phone',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ReactiveFormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatSelectModule,
    TranslocoModule,
  ],
  providers: BaseEditable.getValidableAccessorProvider(EditablePhoneComponent),
  templateUrl: './editable-phone.component.html',
  styleUrls: ['./editable-phone.component.scss'],
})
export class EditablePhoneComponent extends BaseEditable<string> implements OnInit, OnDestroy {
  defaultCountry = input<CountryCode>('ES');
  preferredCountries = input<CountryCode[]>(['ES', 'US', 'GB']);

  dialCode = new FormControl<string>('+34', { nonNullable: true });
  localNumber = new FormControl<string>('', { nonNullable: true });
  countrySearch = signal('');

  selectedCountry = signal<PhoneCountry>(ALL_COUNTRIES.find((c) => c.code === 'ES')!);

  filteredCountries = computed(() => {
    const q = this.countrySearch().toLowerCase();
    const preferred = this.preferredCountries();
    const sorted = [
      ...ALL_COUNTRIES.filter((c) => preferred.includes(c.code)),
      ...ALL_COUNTRIES.filter((c) => !preferred.includes(c.code)),
    ];
    return q ? sorted.filter((c) => c.name.toLowerCase().includes(q) || c.dialCode.includes(q)) : sorted;
  });

  private subs = new Subscription();

  constructor() {
    super();
  }

  override ngOnInit(): void {
    const initial = ALL_COUNTRIES.find((c) => c.code === this.defaultCountry()) ?? ALL_COUNTRIES[0];
    this.selectedCountry.set(initial);
    this.dialCode.patchValue(initial.dialCode);

    super.ngOnInit();
    this.bind([this.dialCode, this.localNumber]);

    this.subs.add(
      this.control.valueChanges.subscribe((external: string | null) => {
        if (!external) return;
        try {
          const parsed = parsePhoneNumber(external);
          const country = ALL_COUNTRIES.find((c) => c.code === parsed.country);
          if (country) {
            this.selectedCountry.set(country);
            this.dialCode.patchValue(country.dialCode, { emitEvent: false });
          }
          this.localNumber.patchValue(parsed.nationalNumber as string, { emitEvent: false });
        } catch {}
      }),
    );

    this.subs.add(this.localNumber.valueChanges.subscribe(() => this.emit()));
    this.subs.add(this.dialCode.valueChanges.subscribe(() => this.emit()));
  }

  override ngOnDestroy(): void {
    this.subs.unsubscribe();
    super.ngOnDestroy();
  }

  selectCountry(country: PhoneCountry): void {
    this.selectedCountry.set(country);
    this.dialCode.patchValue(country.dialCode);
    this.countrySearch.set('');
  }

  override validate(_: any) {
    const raw = this.buildE164();
    if (!raw || raw === this.selectedCountry().dialCode) return null;

    try {
      if (!isValidPhoneNumber(raw)) {
        return { phoneInvalidFormat: true };
      }
    } catch {
      return { phoneInvalidFormat: true };
    }
    return null;
  }

  private emit(): void {
    const e164 = this.buildE164();
    this.updateValue(e164 || null);
  }

  private buildE164(): string {
    const local = this.localNumber.value.replace(/\D/g, '');
    return local ? this.dialCode.value + local : '';
  }
}
